 LinearLayout root,content,nav;LocationManager lm;String role="client",notifiedOfferId="",driverTab="free";JSONObject data;boolean executor=false,online=false;Location lastLocation;Handler handler=new Handler(Looper.getMainLooper());boolean polling=false,waitingForOnline=false;String currentPage="Главная";TextView offerTimer;long offerDeadlineElapsed=0;
