 void driverHomeStats(){JSONObject ui=data.optJSONObject("ui"),h=ui==null?null:ui.optJSONObject("home"),ex=data.optJSONObject("executor"),f=data.optJSONObject("finance"),summary=data.optJSONObject("stats");double rating=h==null?(ex==null?5:ex.optDouble("rating",5)):h.optDouble("rating",5);int completed=h==null?(summary==null?0:summary.optInt("done")):h.optInt("completed_orders");double available=h==null?(f==null?0:f.optDouble("available",0)):h.optDouble("available_balance",0);double today=h==null?0:h.optDouble("today_earnings",0);LinearLayout stats=Ui.card(this);stats.addView(Ui.text(this,"★ "+oneDecimal(rating)+"     "+completed+" заказов",18,true));stats.addView(Ui.text(this,"Доступно "+Math.round(available)+" ₽",21,true));stats.addView(Ui.muted(this,"Сегодня заработано: "+Math.round(today)+" ₽",14));content.addView(stats);}
 void activeOrderPreview(){JSONArray a=data.optJSONArray("orders");if(a==null)return;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String s=o.optString("status");if(!Arrays.asList("assigned","enroute","arrived","loading","in_transit").contains(s))continue;LinearLayout c=Ui.card(this);c.addView(Ui.text(this,"Активный заказ",19,true));order(c,o);content.addView(c);return;}}
 void driverOffer(){JSONArray a=data.optJSONArray("orders");if(a==null)return;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&"offered".equals(o.optString("status"))){String id=o.optString("id");notifiedOfferId=id;LinearLayout c=Ui.card(this);c.addView(Ui.text(this,"НОВЫЙ ЗАКАЗ",21,true));c.addView(Ui.text(this,o.optString("service","Услуга"),18,true));c.addView(Ui.muted(this,"Точка А: "+o.optString("address","Не указана"),14));double nearby=o.optDouble("distance_to_pickup_km",-1);if(nearby>=0)c.addView(Ui.chip(this,"До подачи ≈ "+nearby+" км",true));JSONObject terms=o.optJSONObject("offer_financials");double price=terms==null?o.optDouble("estimated_price",0):terms.optDouble("price",0);double rate=terms==null?(data.optJSONObject("executor")==null?10:data.optJSONObject("executor").optDouble("commission_rate",10)):terms.optDouble("commission_rate",0);double net=terms==null?price*(1-rate/100.0):terms.optDouble("driver_net",0);if(price>0){c.addView(Ui.text(this,Math.round(price)+" ₽",22,true));c.addView(Ui.muted(this,"Комиссия "+Math.round(rate)+"% • вам "+Math.round(net)+" ₽",14));}c.addView(Ui.muted(this,"Точка Б, телефон и комментарий откроются после принятия.",12));int eta=o.optInt("estimated_arrival_min",0);if(eta>0)c.addView(Ui.chip(this,"До клиента ≈ "+eta+" мин",true));int seconds=Math.max(0,Math.min(300,o.optInt("offer_seconds_left",300)));offerDeadlineElapsed=SystemClock.elapsedRealtime()+seconds*1000L;offerTimer=Ui.chip(this,"На принятие: "+offerTimeLeft(),true);c.addView(offerTimer);Button accept=Ui.button(this,"Принять заказ");accept.setOnClickListener(v->acceptAndOpen(id,accept));c.addView(accept);content.addView(c);handler.removeCallbacks(offerTicker);handler.post(offerTicker);break;}}}
 String offerTimeLeft(){long millis=Math.max(0,offerDeadlineElapsed-SystemClock.elapsedRealtime());long left=(millis+999)/1000;return String.format(java.util.Locale.US,"%d:%02d",left/60,left%60);}
