 void driverOrders(String tab){driverTab=tab;page("Заявки");LinearLayout tabs=new LinearLayout(this);tabs.setOrientation(LinearLayout.HORIZONTAL);tabs.addView(Ui.tabButton(this,"Свободные","free".equals(tab),()->driverOrders("free")),new LinearLayout.LayoutParams(0,-2,1));tabs.addView(Ui.tabButton(this,"Назначенные","assigned".equals(tab),()->driverOrders("assigned")),new LinearLayout.LayoutParams(0,-2,1));tabs.addView(Ui.tabButton(this,"Закрытые","closed".equals(tab),()->driverOrders("closed")),new LinearLayout.LayoutParams(0,-2,1));content.addView(tabs);int shown=0;JSONArray regular=data.optJSONArray("orders");if(regular!=null)for(int i=0;i<regular.length();i++){JSONObject item=regular.optJSONObject(i);if(item!=null&&orderInTab(item.optString("status"),tab)){LinearLayout card=Ui.card(this);order(card,item);content.addView(card);shown++;}}JSONArray partner="closed".equals(tab)?data.optJSONArray("partner_order_history"):data.optJSONArray("partner_orders");if(partner!=null)for(int i=0;i<partner.length();i++){JSONObject item=partner.optJSONObject(i);if(item!=null&&partnerInTab(item,tab)){content.addView(partnerOrderCard(item));shown++;}}if(shown==0)content.addView(Ui.muted(this,"free".equals(tab)?"Свободных заявок сейчас нет.":"assigned".equals(tab)?"Назначенных заявок сейчас нет.":"Закрытых заявок пока нет.",15));Button refresh=Ui.darkButton(this,"Обновить");refresh.setOnClickListener(v->refreshQuiet());content.addView(refresh);}
 boolean orderInTab(String status,String tab){boolean closed="done".equals(status)||"completed".equals(status)||"closed".equals(status)||"cancelled".equals(status)||"canceled".equals(status)||"rejected".equals(status);if("closed".equals(tab))return closed;if("free".equals(tab))return "offered".equals(status);return !closed&&!"offered".equals(status);}
 boolean partnerInTab(JSONObject item,String tab){String status=item.optString("status","available");boolean mine=item.optBoolean("is_mine")||!item.optString("assigned_worker_id","").isEmpty();boolean closed="closed".equals(status)||"cancelled".equals(status)||"canceled".equals(status)||"rejected".equals(status);if("closed".equals(tab))return closed;if("free".equals(tab))return !mine&&"available".equals(status);return mine&&!closed;}
 void order(LinearLayout p,JSONObject o){if(o==null)return;String status=o.optString("status"),created=o.optString("created_at","");p.addView(Ui.text(this,o.optString("id")+" • "+o.optString("service"),15,true));p.addView(Ui.chip(this,statusRu(status),"done".equals(status)||"completed".equals(status)||Arrays.asList("assigned","enroute","arrived","loading","in_transit").contains(status)));if(!created.isEmpty())p.addView(Ui.muted(this,created.replace('T',' ').replace("+03:00","").replace("Z",""),12));p.addView(Ui.muted(this,"А: "+o.optString("address","Не указана"),13));if(!o.optBoolean("details_locked",false)&&!o.optString("destination","").isEmpty())p.addView(Ui.muted(this,"Б: "+o.optString("destination"),13));double nearby=o.optDouble("distance_to_pickup_km",-1);if(executor&&nearby>=0)p.addView(Ui.chip(this,"До подачи ≈ "+nearby+" км",true));JSONObject terms=o.optJSONObject("offer_financials");double price=terms==null?o.optDouble("final_price",o.optDouble("estimated_price",0)):terms.optDouble("price",0);if(price>0){p.addView(Ui.text(this,"Стоимость "+Math.round(price)+" ₽",16,true));if(executor&&terms!=null)p.addView(Ui.muted(this,"Комиссия "+Math.round(terms.optDouble("commission"))+" ₽ • вам "+Math.round(terms.optDouble("driver_net"))+" ₽",13));}String id=o.optString("id");p.setOnClickListener(v->openOrder(id));}
 void openOrder(String id){Intent in=new Intent(this,OrderDetailActivity.class);in.putExtra("order_id",id);in.putExtra("role",role);startActivity(in);}
 void partnerOrdersSection(int limit){
  JSONArray rows=data.optJSONArray("partner_orders");
  JSONObject counts=data.optJSONObject("partner_order_counts");
  int available=counts==null?0:counts.optInt("available",0),busy=counts==null?0:counts.optInt("busy",0);
  if((rows==null||rows.length()==0)&&available+busy==0)return;
  content.addView(Ui.text(this,"Заявки партнёра",19,true));
  content.addView(Ui.muted(this,"Свободных заявок: "+available+" • занято другими: "+busy,13));
  if(rows!=null&&rows.length()>0){
   int shown=limit>0?Math.min(limit,rows.length()):rows.length();
   content.addView(Ui.muted(this,"Доступные заявки по дорожному маршруту: "+rows.length(),12));
   for(int i=0;i<shown;i++)content.addView(partnerOrderCard(rows.optJSONObject(i)));
   if(shown<rows.length()){Button all=Ui.darkButton(this,"Показать все доступные ("+rows.length()+")");all.setOnClickListener(v->orders());content.addView(all);}
  }
 }
 java.util.List<JSONObject> sortedPartnerOrders(JSONArray rows){
  java.util.ArrayList<JSONObject> sorted=new java.util.ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject order=rows.optJSONObject(i);if(order!=null)sorted.add(order);}final Location current=freshDriverLocation();
  java.util.Collections.sort(sorted,(a,b)->{int ar=partnerOrderRank(a),br=partnerOrderRank(b);if(ar!=br)return Integer.compare(ar,br);double ad=partnerDistanceMeters(a,current),bd=partnerDistanceMeters(b,current);if(ad!=bd)return Double.compare(ad,bd);return b.optString("created_at","").compareTo(a.optString("created_at",""));});return sorted;
 }
 int partnerOrderRank(JSONObject order){if(order.optBoolean("is_mine"))return 0;return "available".equals(order.optString("status","available"))?1:2;}
 double partnerDistanceMeters(JSONObject order,Location current){if(current==null)return Double.MAX_VALUE;double lat=order.optDouble("pickup_lat",0),lng=order.optDouble("pickup_lng",0);if(lat==0||lng==0)return Double.MAX_VALUE;float[] result=new float[1];Location.distanceBetween(current.getLatitude(),current.getLongitude(),lat,lng,result);return result[0];}
 LinearLayout partnerOrderCard(JSONObject order){
  LinearLayout card=Ui.card(this);boolean mine=order.optBoolean("is_mine");String status=order.optString("status","available");
  String title=order.optString("service","Эвакуация");String vehicle=order.optString("vehicle","");String plate=order.optString("license_plate","");
  card.addView(Ui.text(this,title,18,true));
  String statusText=mine?"● ВАША ТЕКУЩАЯ ЗАЯВКА":"● СВОБОДНАЯ ЗАЯВКА";
  card.addView(Ui.chip(this,statusText,mine||"available".equals(status)));
  card.addView(Ui.routePoint(this,"ТОЧКА А",valueOr(order.optString("pickup_address",""),"Координаты на карте"),false));
  double roadKm=order.optDouble("distance_km",-1);
  if(roadKm>=0){String source=order.optString("distance_source","");card.addView(Ui.chip(this,"≈ "+oneDecimal(roadKm)+("estimated".equals(source)?" км (оценка)":" км по дорогам"),true));}
  else card.addView(Ui.muted(this,"GPS уточняется • расстояние покажет Навигатор",13));
  double lat=order.optDouble("pickup_lat",0),lng=order.optDouble("pickup_lng",0);String address=order.optString("pickup_address","");
  if((lat!=0&&lng!=0)||!address.isEmpty()){Button map=Ui.darkButton(this,"Маршрут к подаче");map.setOnClickListener(v->openYandexMap(lat,lng,address));card.addView(map);}
  LinearLayout details=new LinearLayout(this);details.setOrientation(LinearLayout.VERTICAL);details.setVisibility(android.view.View.GONE);
  if(!vehicle.isEmpty())details.addView(Ui.muted(this,"Автомобиль: "+vehicle,14));if(!plate.isEmpty())details.addView(Ui.muted(this,"Госномер: "+plate,14));
  details.addView(Ui.routePoint(this,"ТОЧКА Б",valueOr(order.optString("destination",""),"Не указано"),true));
  String until=order.optString("service_until","");if(!until.isEmpty())details.addView(Ui.muted(this,"Время работы сервиса: "+until,13));
  String phone=order.optString("phone","");if(!phone.isEmpty()){Button call=Ui.darkButton(this,"Позвонить: "+phone);call.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+Uri.encode(phone)))));details.addView(call);}
  String comment=order.optString("comment","");if(!comment.isEmpty())details.addView(Ui.muted(this,"Комментарий: "+comment,13));
  double destinationLat=order.optDouble("destination_lat",0),destinationLng=order.optDouble("destination_lng",0);String destination=order.optString("destination","");
  if((destinationLat!=0&&destinationLng!=0)||!destination.isEmpty()){Button map=Ui.darkButton(this,"Маршрут к точке Б");map.setOnClickListener(v->openDestinationMap(destinationLat,destinationLng,destination));details.addView(map);}
  Button show=Ui.darkButton(this,"Открыть заявку");show.setOnClickListener(v->{boolean opening=details.getVisibility()!=android.view.View.VISIBLE;details.setVisibility(opening?android.view.View.VISIBLE:android.view.View.GONE);show.setText(opening?"Скрыть детали":"Открыть заявку");});card.addView(show);card.addView(details);
  String id=order.optString("id","");
  if(mine){Button release=Ui.darkButton(this,"Вернуть в общий список");release.setOnClickListener(v->partnerAction(id,"release",release));card.addView(release);}
  else if("available".equals(status)){Button claim=Ui.button(this,order.optBoolean("can_claim",false)?"Взять в работу":"Ожидает очереди");claim.setEnabled(order.optBoolean("can_claim",false));claim.setOnClickListener(v->partnerAction(id,"claim",claim));card.addView(claim);}
  return card;
 }
 String valueOr(String value,String fallback){return value==null||value.trim().isEmpty()?fallback:value;}
 void partnerAction(String id,String action,Button button){
  button.setEnabled(false);button.setText("claim".equals(action)?"Принимаем…":"Возвращаем…");
  new Thread(()->{try{JSONObject r=ApiClient.post("/api/partner_order_action.php",new JSONObject().put("order_id",id).put("action",action));runOnUiThread(()->{if(r.optBoolean("ok")){driverTab="claim".equals(action)?"assigned":"free";Toast.makeText(this,"claim".equals(action)?"Заявка закреплена за вами":"Заявка возвращена в список",Toast.LENGTH_LONG).show();refreshQuiet();}else{button.setEnabled(true);button.setText("claim".equals(action)?"Взять в работу":"Вернуть в общий список");Toast.makeText(this,partnerError(r.optString("error")),Toast.LENGTH_LONG).show();}});}catch(Exception e){runOnUiThread(()->{button.setEnabled(true);Toast.makeText(this,"Нет связи с AV Rescue",Toast.LENGTH_LONG).show();});}}).start();
 }
 String partnerError(String error){if("ALREADY_CLAIMED".equals(error))return "Эту заявку уже взял другой водитель";if("GO_ONLINE_FIRST".equals(error))return "Сначала выйдите на линию";if("ORDER_CLOSED".equals(error))return "Заявка уже закрыта";if("OWN_FLEET_ONLY".equals(error))return "Заявка доступна только собственному парку";if("WORKER_BUSY".equals(error))return "Сначала завершите текущую заявку";if("NEXT_ORDER_ALREADY_QUEUED".equals(error))return "Следующая заявка уже назначена";return error==null||error.isEmpty()||error.matches("[A-Z0-9_]+")?"Не удалось обновить заявку":error;}
 void openYandexMap(double lat,double lng,String address){
  Uri uri=(lat!=0&&lng!=0)?Uri.parse("yandexnavi://build_route_on_map?lat_to="+lat+"&lon_to="+lng):Uri.parse("https://yandex.ru/maps/?text="+Uri.encode(address));
  Intent intent=new Intent(Intent.ACTION_VIEW,uri);intent.setPackage("ru.yandex.yandexnavi");
  try{startActivity(intent);}catch(Exception e){Uri web=(lat!=0&&lng!=0)?Uri.parse("https://yandex.ru/maps/?ll="+lng+"%2C"+lat+"&z=16&pt="+lng+"%2C"+lat+"%2Cpm2rdm"):Uri.parse("https://yandex.ru/maps/?text="+Uri.encode(address));try{startActivity(new Intent(Intent.ACTION_VIEW,web));}catch(Exception ignored){Toast.makeText(this,"Не удалось открыть Яндекс Карты",Toast.LENGTH_SHORT).show();}}
 }
 void openDestinationMap(double lat,double lng,String address){String exact=address==null?"":address.trim();if(exact.isEmpty()){openYandexMap(lat,lng,exact);return;}Uri route=Uri.parse("yandexmaps://maps.yandex.ru/?rtext=~"+Uri.encode(exact)+"&rtt=auto");Intent intent=new Intent(Intent.ACTION_VIEW,route);intent.setPackage("ru.yandex.yandexmaps");try{startActivity(intent);}catch(Exception e){Uri web=Uri.parse("https://yandex.ru/maps/?rtext=~"+Uri.encode(exact)+"&rtt=auto");try{startActivity(new Intent(Intent.ACTION_VIEW,web));}catch(Exception ignored){Toast.makeText(this,"Не удалось открыть адрес точки Б",Toast.LENGTH_SHORT).show();}}}
 void linePage(){page("Работа на линии");LinearLayout c=Ui.card(this);c.addView(Ui.text(this,online?"Вы на линии":"Вы не на линии",24,true));c.addView(Ui.chip(this,online?"● GPS АКТИВЕН":"● ЗАЯВКИ НЕ ПОСТУПАЮТ",online));c.addView(Ui.muted(this,online?"AV Rescue получает вашу геопозицию и предлагает подходящие заявки.":"Выйдите на линию, чтобы система начала предлагать заказы.",14));Button toggle=Ui.primaryButton(this,online?"Уйти с линии":"Выйти на линию");toggle.setOnClickListener(v->{if(online)goOffline();else startLocationUpdates();});c.addView(toggle);Button refresh=Ui.darkButton(this,"Обновить заказы");refresh.setOnClickListener(v->refreshQuiet());c.addView(refresh);content.addView(c);driverOffer();partnerOrdersSection(0);}
 void startLocationUpdates(){lm=(LocationManager)getSystemService(LOCATION_SERVICE);if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},90);return;}waitingForOnline=true;Toast.makeText(this,"Получаем свежую GPS-точку…",Toast.LENGTH_SHORT).show();try{if(lm.isProviderEnabled(LocationManager.GPS_PROVIDER))lm.requestLocationUpdates(LocationManager.GPS_PROVIDER,10000,0,this);if(lm.isProviderEnabled(LocationManager.NETWORK_PROVIDER))lm.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,10000,0,this);Location x=bestFreshLocation(lm.getLastKnownLocation(LocationManager.GPS_PROVIDER),lm.getLastKnownLocation(LocationManager.NETWORK_PROVIDER));if(x!=null){waitingForOnline=false;sendLocation(x,true);}}catch(Exception e){Toast.makeText(this,"Включите геолокацию",Toast.LENGTH_LONG).show();}}
 void startDriverService(){Intent service=new Intent(this,DriverLocationService.class).setAction(DriverLocationService.ACTION_START);if(Build.VERSION.SDK_INT>=26)startForegroundService(service);else startService(service);}
 void stopDriverService(){stopService(new Intent(this,DriverLocationService.class));}
 void stopOfferAlert(){Intent service=new Intent(this,DriverLocationService.class).setAction(DriverLocationService.ACTION_STOP_ALERT);if(Build.VERSION.SDK_INT>=26)startForegroundService(service);else startService(service);}
 void goOffline(){stopOfferAlert();stopDriverService();if(lm==null)lm=(LocationManager)getSystemService(LOCATION_SERVICE);try{lm.removeUpdates(this);}catch(Exception ignored){}Location x=lastLocation;try{if(x==null&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)x=lm.getLastKnownLocation(LocationManager.GPS_PROVIDER);}catch(Exception ignored){}if(x==null){long a=getSharedPreferences("avr",MODE_PRIVATE).getLong("last_lat",0),b=getSharedPreferences("avr",MODE_PRIVATE).getLong("last_lng",0);if(a!=0&&b!=0){x=new Location("saved");x.setLatitude(Double.longBitsToDouble(a));x.setLongitude(Double.longBitsToDouble(b));}}if(x==null){Toast.makeText(this,"Сначала дождитесь GPS",Toast.LENGTH_LONG).show();return;}sendLocation(x,false);}
 boolean isFreshLocation(Location l){if(l==null||l.getTime()<=0||System.currentTimeMillis()-l.getTime()>MAX_LOCATION_AGE_MS)return false;return !l.hasAccuracy()||l.getAccuracy()<=MAX_LOCATION_ACCURACY_M;}
 Location bestFreshLocation(Location a,Location b){boolean af=isFreshLocation(a),bf=isFreshLocation(b);if(!af)return bf?b:null;if(!bf)return a;if(Math.abs(a.getTime()-b.getTime())>30000)return a.getTime()>b.getTime()?a:b;if(a.hasAccuracy()&&b.hasAccuracy())return a.getAccuracy()<=b.getAccuracy()?a:b;return a.getTime()>=b.getTime()?a:b;}
 void cacheLocation(Location l){lastLocation=l;getSharedPreferences("avr",MODE_PRIVATE).edit().putLong("last_lat",Double.doubleToRawLongBits(l.getLatitude())).putLong("last_lng",Double.doubleToRawLongBits(l.getLongitude())).putLong("last_fix_time",l.getTime()).putFloat("last_accuracy",l.hasAccuracy()?l.getAccuracy():0).apply();}
 Location freshDriverLocation(){if(isFreshLocation(lastLocation))return lastLocation;android.content.SharedPreferences p=getSharedPreferences("avr",MODE_PRIVATE);long a=p.getLong("last_lat",0),b=p.getLong("last_lng",0),time=p.getLong("last_fix_time",0);if(a==0||b==0||time<=0||System.currentTimeMillis()-time>MAX_LOCATION_AGE_MS)return null;Location x=new Location("cached");x.setLatitude(Double.longBitsToDouble(a));x.setLongitude(Double.longBitsToDouble(b));x.setTime(time);float accuracy=p.getFloat("last_accuracy",0);if(accuracy>0)x.setAccuracy(accuracy);return isFreshLocation(x)?x:null;}
 void sendLocation(Location l,boolean on){if(on&&!isFreshLocation(l)){waitingForOnline=true;Toast.makeText(this,"Ждём свежую GPS-точку",Toast.LENGTH_SHORT).show();return;}if(on)cacheLocation(l);lastLocation=l;new Thread(()->{try{JSONObject r=ApiClient.post("/api/mobile_location.php",new JSONObject().put("lat",l.getLatitude()).put("lng",l.getLongitude()).put("accuracy_m",l.hasAccuracy()?l.getAccuracy():JSONObject.NULL).put("captured_at_ms",l.getTime()).put("online",on));runOnUiThread(()->{if(r.optBoolean("ok")){online=on;waitingForOnline=false;if(on)startDriverService();else stopDriverService();Toast.makeText(this,on?"Вы на линии":"Вы не на линии",Toast.LENGTH_SHORT).show();setupNav();linePage();}else Toast.makeText(this,r.optString("error","Ошибка GPS"),Toast.LENGTH_LONG).show();});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Нет связи с AV Rescue",Toast.LENGTH_LONG).show());}}).start();}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==90&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startLocationUpdates();}
 public void onLocationChanged(Location l){if(!isFreshLocation(l))return;cacheLocation(l);if(!executor)return;if(waitingForOnline){waitingForOnline=false;sendLocation(l,true);}else if(online)sendLocationSilent(l);}
 void sendLocationSilent(Location l){if(!isFreshLocation(l))return;cacheLocation(l);new Thread(()->{try{ApiClient.post("/api/mobile_location.php",new JSONObject().put("lat",l.getLatitude()).put("lng",l.getLongitude()).put("accuracy_m",l.hasAccuracy()?l.getAccuracy():JSONObject.NULL).put("captured_at_ms",l.getTime()).put("online",true));online=true;}catch(Exception ignored){}}).start();}
 public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}public void onStatusChanged(String p,int s,Bundle b){}
 void finance(){
  page("Доход и комиссия");JSONObject f=data.optJSONObject("finance"),ex=data.optJSONObject("executor");LinearLayout c=Ui.card(this);
  if(f==null){c.addView(Ui.muted(this,"Финансовых операций пока нет.",14));}
  else{
   double balance=f.optDouble("current_balance",ex==null?0:ex.optDouble("balance",0)),available=f.optDouble("available",Math.max(0,balance)),debt=f.optDouble("debt",Math.max(0,-balance));
   c.addView(Ui.text(this,"Доступно к выплате: "+Math.round(available)+" ₽",20,true));c.addView(Ui.text(this,"Текущий баланс: "+Math.round(balance)+" ₽",18,true));
   if(debt>0)c.addView(Ui.chip(this,"Задолженность AV Rescue: "+Math.round(debt)+" ₽",false));
   if(f.optDouble("requested",0)>0)c.addView(Ui.muted(this,"Ожидает выплаты: "+Math.round(f.optDouble("requested"))+" ₽",14));
   c.addView(Ui.muted(this,"Заказы: "+Math.round(f.optDouble("gross"))+" ₽",14));c.addView(Ui.muted(this,"Ваш заработок: "+Math.round(f.optDouble("earned"))+" ₽",14));c.addView(Ui.muted(this,"Комиссия AV Rescue: "+Math.round(f.optDouble("commission"))+" ₽",14));
  }
  if(ex!=null)c.addView(Ui.muted(this,"Текущая ставка комиссии: "+Math.round(ex.optDouble("commission_rate",10))+"%",14));content.addView(c);
  JSONObject account=data.optJSONObject("payout_account");LinearLayout accountCard=Ui.card(this);accountCard.addView(Ui.text(this,"Куда получать деньги",19,true));boolean accountReady=account!=null&&account.optBoolean("ready",account.optBoolean("is_ready",false));accountCard.addView(Ui.muted(this,accountReady?account.optString("method_label","Способ выплаты")+" • "+account.optString("account_mask",account.optString("masked","")):"Способ выплаты ещё не настроен",14));Button editAccount=Ui.darkButton(this,accountReady?"Изменить реквизиты":"Настроить способ выплаты");editAccount.setOnClickListener(v->showPayoutAccountDialog());accountCard.addView(editAccount);content.addView(accountCard);
  if(f!=null){double available=f.optDouble("available",0);if(available>=4000){LinearLayout payout=Ui.card(this);payout.addView(Ui.text(this,"Заказать выплату",19,true));payout.addView(Ui.muted(this,"Введите сумму. Деньги придут на сохранённые реквизиты в ближайший платёжный день — вторник или пятницу.",13));EditText amount=Ui.input(this,"Сумма, ₽ (от 4 000)");amount.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);payout.addView(amount);Button send=Ui.button(this,"Запросить выплату");send.setEnabled(accountReady);send.setOnClickListener(v->requestPayout(amount,send));payout.addView(send);if(!accountReady)payout.addView(Ui.muted(this,"Сначала сохраните способ выплаты.",12));content.addView(payout);}else if(available>0){LinearLayout minimum=Ui.card(this);minimum.addView(Ui.text(this,"До выплаты осталось "+Math.round(4000-available)+" ₽",17,true));minimum.addView(Ui.muted(this,"Минимальная сумма выплаты — 4 000 ₽.",13));content.addView(minimum);}}
  if(f!=null){JSONArray payouts=f.optJSONArray("payouts");LinearLayout payoutHistory=Ui.card(this);payoutHistory.addView(Ui.text(this,"Выплаты",19,true));if(payouts==null||payouts.length()==0)payoutHistory.addView(Ui.muted(this,"Заявок на выплату пока нет.",14));else for(int i=0;i<payouts.length();i++){JSONObject x=payouts.optJSONObject(i);if(x==null)continue;payoutHistory.addView(Ui.text(this,x.optString("id","Выплата")+" • "+Math.round(x.optDouble("amount"))+" ₽",15,true));payoutHistory.addView(Ui.chip(this,payoutStatus(x.optString("status")),"paid".equals(x.optString("status"))));}content.addView(payoutHistory);}
  if(f!=null){JSONArray tx=f.optJSONArray("transactions");LinearLayout history=Ui.card(this);history.addView(Ui.text(this,"История по заказам",19,true));if(tx==null||tx.length()==0)history.addView(Ui.muted(this,"Операций пока нет.",14));else for(int i=0;i<tx.length();i++){JSONObject x=tx.optJSONObject(i);if(x==null)continue;boolean cash="cash".equals(x.optString("payment_method"));history.addView(Ui.text(this,x.optString("order_id","Заказ")+" • "+Math.round(x.optDouble("price"))+" ₽",16,true));history.addView(Ui.muted(this,(cash?"Наличные":"Оплата картой")+" • комиссия "+Math.round(x.optDouble("commission"))+" ₽",13));double change=x.optDouble("balance_change");history.addView(Ui.muted(this,(change>=0?"Зачислено: +":"Списано: ")+Math.round(Math.abs(change))+" ₽",13));}content.addView(history);}
 }
 void showPayoutAccountDialog(){LinearLayout form=Ui.column(this);Spinner method=new Spinner(this);String[] methods={"СБП","Банковская карта","Расчётный счёт"};method.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,methods));EditText holder=Ui.input(this,"Получатель — ФИО"),primary=Ui.input(this,"Телефон СБП"),bik=Ui.input(this,"БИК — только для счёта"),bank=Ui.input(this,"Название банка");form.addView(method);form.addView(holder);form.addView(primary);form.addView(bik);form.addView(bank);method.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int x,long id){primary.setHint(x==0?"Телефон СБП":x==1?"Номер банковской карты":"Номер расчётного счёта (20 цифр)");bik.setVisibility(x==2?View.VISIBLE:View.GONE);}});JSONObject p=data.optJSONObject("profile"),old=data.optJSONObject("payout_account");holder.setText(old==null?(p==null?"":p.optString("name","")):old.optString("holder_name",p==null?"":p.optString("name","")));bank.setText(old==null?"":old.optString("bank_name",""));new AlertDialog.Builder(this).setTitle("Способ выплаты").setView(form).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->savePayoutAccount(method.getSelectedItemPosition(),holder.getText().toString(),primary.getText().toString(),bik.getText().toString(),bank.getText().toString())).show();}
 void savePayoutAccount(int selected,String holder,String value,String bik,String bank){String method=selected==0?"sbp":selected==1?"card":"bank_account";JSONObject body=new JSONObject();try{body.put("method",method).put("holder_name",holder).put("bank_name",bank);if("sbp".equals(method))body.put("phone",value);else if("card".equals(method))body.put("card_number",value);else body.put("bank_account",value).put("bik",bik);}catch(Exception ignored){}new Thread(()->{try{JSONObject r=ApiClient.post("/api/payout_account.php",body);runOnUiThread(()->{Toast.makeText(this,r.optBoolean("ok")?"Способ выплаты сохранён":r.optString("error","Не удалось сохранить"),Toast.LENGTH_LONG).show();if(r.optBoolean("ok"))load();});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Нет связи с AV Rescue",Toast.LENGTH_LONG).show());}}).start();}
 void requestPayout(EditText amountField,Button button){double amount;try{amount=Double.parseDouble(amountField.getText().toString().trim().replace(',','.'));}catch(Exception e){Toast.makeText(this,"Укажите сумму выплаты",Toast.LENGTH_LONG).show();return;}double available=data.optJSONObject("finance")==null?0:data.optJSONObject("finance").optDouble("available",0);if(amount<4000){Toast.makeText(this,"Минимальная сумма выплаты — 4 000 ₽",Toast.LENGTH_LONG).show();return;}if(amount>available){Toast.makeText(this,"Недостаточно доступных средств",Toast.LENGTH_LONG).show();return;}button.setEnabled(false);button.setText("Отправляем…");new Thread(()->{try{JSONObject r=ApiClient.post("/api/mobile_payout.php",new JSONObject().put("amount",amount));runOnUiThread(()->{if(r.optBoolean("ok")){Toast.makeText(this,"Заявка "+r.optString("payout_id")+" создана",Toast.LENGTH_LONG).show();refreshQuiet();}else{button.setEnabled(true);button.setText("Запросить выплату");Toast.makeText(this,r.optString("error","Заявка не создана"),Toast.LENGTH_LONG).show();}});}catch(Exception e){runOnUiThread(()->{button.setEnabled(true);button.setText("Запросить выплату");Toast.makeText(this,"Нет связи с AV Rescue",Toast.LENGTH_LONG).show();});}}).start();}
 String payoutStatus(String status){if("new".equals(status))return "● На рассмотрении";if("approved".equals(status))return "● Одобрена";if("processing".equals(status))return "● Передана в банк";if("paid".equals(status))return "● Выплачена";if("failed".equals(status))return "● Ошибка выплаты";if("rejected".equals(status))return "● Отклонена";return "● "+status;}
